CREATE OR REPLACE FUNCTION public.fc_get_combat() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c public.fc_characters; e public.fc_combat_encounters; m public.fc_monster_definitions; current_room uuid; safe boolean;
BEGIN SELECT * INTO c FROM public.fc_characters WHERE owner_id=public.fc_require_uid(); SELECT r.id,r.is_safe_city INTO current_room,safe FROM public.fc_character_positions p JOIN public.fc_world_cells cell ON cell.id=p.cell_id JOIN public.fc_world_rooms r ON r.id=cell.room_id WHERE p.character_id=c.id; IF coalesce(safe,true) THEN RETURN jsonb_build_object('active',false); END IF; SELECT * INTO e FROM public.fc_combat_encounters WHERE character_id=c.id AND room_id=current_room AND status IN ('active','won','lost') AND (status='active' OR tick_at>now()-interval '30 seconds') ORDER BY created_at DESC LIMIT 1; IF e.id IS NULL THEN RETURN jsonb_build_object('active',false); END IF; SELECT * INTO m FROM public.fc_monster_definitions WHERE id=e.monster_id; RETURN jsonb_build_object('active',e.status='active','encounter',to_jsonb(e),'monster',to_jsonb(m),'player_realm',c.realm,'player_name',c.display_name,'player_avatar_key',c.avatar_key); END $$;
